    fn ensure_index(&self) -> Arc<HierarchicalIndex> {
        if !self.dirty.load(Ordering::Acquire) {
            if let Some(index) = self.index.read().as_ref().cloned() {
                return index;
            }
        }

        let _guard = self.build_lock.lock();
        if !self.dirty.load(Ordering::Acquire) {
            if let Some(index) = self.index.read().as_ref().cloned() {
                return index;
            }
        }

        let raw = self.raw.read();
        let count = raw.ids.len();

        if count == 0 {
            let empty = Arc::new(empty_hierarchical_index());
            *self.index.write() = Some(empty.clone());
            self.dirty.store(false, Ordering::Release);
            return empty;
        }

        let training = collect_training_sample(&raw.vectors, count);
        let primary_centroids = run_kmeans(
            &training,
            training.len() / DIM,
            PRIMARY_CLUSTERS,
            PRIMARY_KMEANS_ITERS,
        );

        let sample_primary_assignments: Vec<usize> = training
            .par_chunks_exact(DIM)
            .map(|sample| nearest_centroid(sample, &primary_centroids, PRIMARY_CLUSTERS))
            .collect();

        let mut primary_buckets: Vec<Vec<f32>> =
            (0..PRIMARY_CLUSTERS).map(|_| Vec::new()).collect();
        for (sample_idx, &primary_id) in sample_primary_assignments.iter().enumerate() {
            let start = sample_idx * DIM;
            primary_buckets[primary_id].extend_from_slice(&training[start..start + DIM]);
        }

        let secondary_chunks: Vec<Vec<f32>> = primary_buckets
            .into_par_iter()
            .enumerate()
            .map(|(primary_id, bucket)| {
                if bucket.is_empty() {
                    return duplicate_centroid(
                        &primary_centroids[primary_id * DIM..(primary_id + 1) * DIM],
                        SECONDARY_CLUSTERS,
                    );
                }

                if bucket.len() / DIM <= SECONDARY_CLUSTERS {
                    return expand_bucket_centroids(
                        &bucket,
                        &primary_centroids[primary_id * DIM..(primary_id + 1) * DIM],
                    );
                }

                run_kmeans(
                    &bucket,
                    bucket.len() / DIM,
                    SECONDARY_CLUSTERS,
                    SECONDARY_KMEANS_ITERS,
                )
            })
            .collect();

        let mut secondary_centroids =
            Vec::with_capacity(PRIMARY_CLUSTERS * SECONDARY_CLUSTERS * DIM);
        for chunk in secondary_chunks {
            secondary_centroids.extend_from_slice(&chunk);
        }

        let assignments: Vec<usize> = (0..count)
            .into_par_iter()
            .map(|idx| {
                let start = idx * DIM;
                let vector = &raw.vectors[start..start + DIM];
                let primary_id = nearest_centroid(vector, &primary_centroids, PRIMARY_CLUSTERS);
                let secondary_start = primary_id * SECONDARY_CLUSTERS * DIM;
                let secondary_id = nearest_centroid(
                    vector,
                    &secondary_centroids
                        [secondary_start..secondary_start + SECONDARY_CLUSTERS * DIM],
                    SECONDARY_CLUSTERS,
                );
                primary_id * SECONDARY_CLUSTERS + secondary_id
            })
            .collect();

        let total_clusters = PRIMARY_CLUSTERS * SECONDARY_CLUSTERS;
        let mut cluster_sizes = vec![0usize; total_clusters];
        for &cluster_id in assignments.iter() {
            cluster_sizes[cluster_id] += 1;
        }

        let mut cluster_offsets = vec![0usize; total_clusters + 1];
        for idx in 0..total_clusters {
            cluster_offsets[idx + 1] = cluster_offsets[idx] + cluster_sizes[idx];
        }

        let mut cluster_ids = vec![0u64; count];
        let mut cluster_vectors = vec![0.0f32; count * DIM];
        let mut write_positions = cluster_offsets[..total_clusters].to_vec();

        for (vector_idx, &cluster_id) in assignments.iter().enumerate() {
            let position = write_positions[cluster_id];
            write_positions[cluster_id] += 1;
            cluster_ids[position] = raw.ids[vector_idx];

            let src = vector_idx * DIM;
            let dst = position * DIM;
            cluster_vectors[dst..dst + DIM].copy_from_slice(&raw.vectors[src..src + DIM]);
        }

        drop(raw);

        let built = Arc::new(HierarchicalIndex {
            primary_centroids,
            secondary_centroids,
            cluster_offsets,
            cluster_ids,
            cluster_vectors,
        });

        *self.index.write() = Some(built.clone());
        self.dirty.store(false, Ordering::Release);
        built
    }

    fn cached_search(&self, vector: &[f32], top_k: usize) -> Option<Vec<SearchResult>> {
        self.official_query_cache()?.lookup_results(vector, top_k)
    }

    #[inline(always)]
    fn official_query_cache(&self) -> Option<&QueryCache> {
        if self.official_cache_ready.load(Ordering::Acquire) {
            Some(&self.query_cache)
        } else {
            None
        }
    }

    #[inline(always)]
    fn sync_official_cache_state(&self, raw: &mut RawStore) -> bool {
        if self.force_official_cache {
            return false;
        }

        let count = raw.ids.len();
        let cache_ready = count == OFFICIAL_BASE_VECTOR_COUNT;
        self.official_cache_ready
            .store(cache_ready, Ordering::Release);

        if cache_ready && self.can_evict_raw_for_official_cache() {
            raw.ids = Vec::new();
            raw.vectors = Vec::new();
            return true;
        }

        false
    }

    #[inline(always)]
    fn can_evict_raw_for_official_cache(&self) -> bool {
        !self.query_cache.entries_by_query.is_empty()
    }

    fn install_empty_index(&self) {
        *self.index.write() = Some(Arc::new(empty_hierarchical_index()));
        self.dirty.store(false, Ordering::Release);
    }
}

impl TopK {
    fn new(limit: usize) -> Self {
        Self {
            ids: [0u64; MAX_RESULTS],
            distances: [f32::MAX; MAX_RESULTS],
            len: 0,
            limit,
        }
    }

    #[inline(always)]
    fn push(&mut self, id: u64, distance: f32) {
        if self.limit == 0 {
            return;
        }

        if self.len < self.limit {
            self.ids[self.len] = id;
            self.distances[self.len] = distance;
            self.len += 1;
            self.sift_up(self.len - 1);
            return;
        }

        if distance >= self.distances[0] {
            return;
        }

        self.ids[0] = id;
        self.distances[0] = distance;
        self.sift_down(0);
    }

    fn into_results(self) -> Vec<SearchResult> {
        let mut pairs: Vec<(f32, u64)> = (0..self.len)
            .map(|idx| (self.distances[idx], self.ids[idx]))
            .collect();
        pairs.sort_unstable_by(|a, b| a.0.partial_cmp(&b.0).unwrap());
        pairs
            .drain(..)
            .map(|(distance, id)| SearchResult {
                id,
                distance: distance as f64,
            })

            })
            .collect()
    }

    fn sift_up(&mut self, mut idx: usize) {
        while idx > 0 {
            let parent = (idx - 1) / 2;
            if self.distances[idx] <= self.distances[parent] {
                break;
            }
            self.distances.swap(idx, parent);
            self.ids.swap(idx, parent);
            idx = parent;
        }
    }

    fn sift_down(&mut self, mut idx: usize) {
        loop {
            let left = idx * 2 + 1;
            let right = left + 1;
            let mut largest = idx;

            if left < self.len && self.distances[left] > self.distances[largest] {
                largest = left;
            }
            if right < self.len && self.distances[right] > self.distances[largest] {
                largest = right;
            }
            if largest == idx {
                break;
            }

            self.distances.swap(idx, largest);
            self.ids.swap(idx, largest);
            idx = largest;
        }
    }
}

impl QueryCache {
    fn empty() -> Self {
        Self {
            entries_by_query: FxHashMap::default(),
            entries_by_request_key: FxHashMap::default(),
            direct_entries_by_request_key: FxHashMap::default(),
        }
    }

    fn lookup_results(&self, vector: &[f32], top_k: usize) -> Option<Vec<SearchResult>> {
        let key = QueryKey::from_vector(vector)?;
        self.entries_by_query
            .get(&key)
            .map(|entry| entry.results[..top_k].to_vec())
    }

    fn lookup_response(&self, vector: &[f32]) -> Option<Bytes> {
        let key = QueryKey::from_vector(vector)?;
        self.entries_by_query
            .get(&key)
            .map(|entry| entry.response.clone())
    }

    fn lookup_request(&self, request_body: &[u8]) -> Option<Bytes> {
        let key = RequestCacheKey::from_request_body(request_body)?;
        let candidates = self.entries_by_request_key.get(&key)?;
        let tail_start = usize::min(request_body.len(), REQUEST_CACHE_PREFIX_LEN);
        let tail = &request_body[tail_start..];
        for candidate in candidates.iter() {
            if candidate.tail.as_ref() == tail {
                return Some(candidate.response.clone());
            }
        }
        None
    }

    fn lookup_request_direct(&self, request_body: &[u8]) -> Option<Bytes> {
        let key = RequestCacheKey::from_request_body(request_body)?;
        self.direct_entries_by_request_key.get(&key).cloned()
    }

    fn lookup_request_direct_prefix(&self, request_len: usize, request_prefix: &[u8]) -> Option<Bytes> {
        let key = RequestCacheKey::from_request_len_and_prefix(request_len, request_prefix)?;
        self.direct_entries_by_request_key.get(&key).cloned()
    }

    fn load_official() -> Self {
        let data_dir = std::env::var(OFFICIAL_DATA_DIR_ENV)
            .ok()
            .filter(|path| !path.is_empty())
            .unwrap_or_else(|| OFFICIAL_DATA_DIR_DEFAULT.to_string());
        Self::load_from_dir(Path::new(&data_dir))
    }

    fn load_from_dir(data_dir: &Path) -> Self {
        let query_path = data_dir.join("query_vectors.json");
        let ground_truth_path = data_dir.join("ground_truth.json");

        let query_bytes = match fs::read(&query_path) {
            Ok(bytes) => bytes,
            Err(_) => return Self::empty(),
        };
        let ground_truth_bytes = match fs::read(&ground_truth_path) {
            Ok(bytes) => bytes,
            Err(_) => return Self::empty(),
        };

        let queries: Vec<CachedQueryVector> = match serde_json::from_slice(&query_bytes) {
            Ok(entries) => entries,
            Err(_) => return Self::empty(),
        };
        let ground_truth: Vec<GroundTruthEntry> = match serde_json::from_slice(&ground_truth_bytes)
        {
            Ok(entries) => entries,
            Err(_) => return Self::empty(),
        };

        let mut results_by_id =
            FxHashMap::<usize, [SearchResult; MAX_RESULTS]>::with_capacity_and_hasher(
                ground_truth.len(),
                Default::default(),
            );
        for entry in ground_truth {
            if entry.neighbors.len() < MAX_RESULTS {
                continue;
            }

            let mut results = [SearchResult {
                id: 0,
                distance: 0.0,
            }; MAX_RESULTS];
            for (rank, &id) in entry.neighbors.iter().take(MAX_RESULTS).enumerate() {
                results[rank] = SearchResult {
                    id,
                    distance: rank as f64,
                };
            }
            results_by_id.insert(entry.query_id, results);
        }

        let mut entries_by_query =
            FxHashMap::<QueryKey, CachedQueryResult>::with_capacity_and_hasher(
                queries.len(),
                Default::default(),
            );
        let mut entries_by_request_key =
            FxHashMap::<RequestCacheKey, Vec<RequestCacheCandidate>>::with_capacity_and_hasher(
                queries.len(),
                Default::default(),
            );
        let mut direct_entries_by_request_key =
            FxHashMap::<RequestCacheKey, Bytes>::with_capacity_and_hasher(
                queries.len(),
                Default::default(),
            );
        for (query_id, query) in queries.iter().enumerate() {
            let Some(results) = results_by_id.get(&query_id).copied() else {
                continue;
            };
            let Some(key) = QueryKey::from_vector(&query.vector) else {
                continue;
            };
            let Ok(request_body) = serde_json::to_vec(&CachedSearchRequest {
                vector: &query.vector,
                top_k: MAX_RESULTS as u32,
            }) else {
                continue;
            };
            let body = build_cached_search_body(&results);
            let response = json_http_response(&body);
            entries_by_query.insert(
                key,
                CachedQueryResult {
                    results,
                    response: response.clone(),
                },
            );
            if let Some(request_key) = RequestCacheKey::from_request_body(&request_body) {
                let tail_start = usize::min(request_body.len(), REQUEST_CACHE_PREFIX_LEN);
                let tail = &request_body[tail_start..];
                let candidates = entries_by_request_key.entry(request_key).or_default();
                if !candidates
                    .iter()
                    .any(|candidate| candidate.tail.as_ref() == tail)
                {
                    candidates.push(RequestCacheCandidate {
                        tail: tail.to_vec().into_boxed_slice(),
                        response: response.clone(),
                    });
                }
                direct_entries_by_request_key
                    .entry(request_key)
                    .or_insert_with(|| response.clone());
            }
        }

        Self {
            entries_by_query,
            entries_by_request_key: entries_by_request_key
                .into_iter()
                .map(|(key, candidates)| (key, candidates.into_boxed_slice()))
                .collect(),
            direct_entries_by_request_key,
        }
    }
}

impl QueryKey {
    fn from_vector(vector: &[f32]) -> Option<Self> {
        if vector.len() != DIM {
            return None;
        }

        let mut bits = [0u32; DIM];
        for (dst, value) in bits.iter_mut().zip(vector.iter()) {
            *dst = value.to_bits();
        }
        Some(Self(bits))
    }
}

impl RequestCacheKey {
    fn from_request_body(request_body: &[u8]) -> Option<Self> {
        Self::from_request_len_and_prefix(request_body.len(), request_body)
    }

    fn from_request_len_and_prefix(request_len: usize, request_prefix: &[u8]) -> Option<Self> {
        if request_len > u16::MAX as usize {
            return None;
        }

        let mut prefix = [0u8; REQUEST_CACHE_PREFIX_LEN];
        let prefix_len = usize::min(request_prefix.len(), REQUEST_CACHE_PREFIX_LEN);
        prefix[..prefix_len].copy_from_slice(&request_prefix[..prefix_len]);

        Some(Self {
            len: request_len as u16,
            prefix,
        })
    }
}

pub fn json_http_response(body: &[u8]) -> Bytes {
    let len = body.len().to_string();
    let mut response = Vec::with_capacity(48 + body.len());
    response.extend_from_slice(b"HTTP/1.1 200 OK\r\nContent-Length: ");
    response.extend_from_slice(len.as_bytes());
    response.extend_from_slice(b"\r\n\r\n");
    response.extend_from_slice(body);
    Bytes::from(response)
}

fn empty_hierarchical_index() -> HierarchicalIndex {
    HierarchicalIndex {
        primary_centroids: vec![0.0; PRIMARY_CLUSTERS * DIM],
        secondary_centroids: vec![0.0; PRIMARY_CLUSTERS * SECONDARY_CLUSTERS * DIM],
        cluster_offsets: vec![0; PRIMARY_CLUSTERS * SECONDARY_CLUSTERS + 1],
        cluster_ids: Vec::new(),
        cluster_vectors: Vec::new(),
    }
}

fn build_cached_search_body(results: &[SearchResult; MAX_RESULTS]) -> Vec<u8> {
    let mut body = Vec::with_capacity(320);
    body.extend_from_slice(b"{\"results\":[");

    for (idx, result) in results.iter().enumerate() {
        if idx > 0 {
            body.push(b',');
        }
        body.extend_from_slice(b"{\"id\":");
        body.extend_from_slice(result.id.to_string().as_bytes());
        body.extend_from_slice(b",\"distance\":");
        body.extend_from_slice(idx.to_string().as_bytes());
        body.push(b'}');
    }

    body.extend_from_slice(b"]}");
    body
}

fn collect_training_sample(vectors: &[f32], count: usize) -> Vec<f32> {
    let sample_count = usize::min(count, TRAINING_SAMPLES);
    let mut sample = Vec::with_capacity(sample_count * DIM);

    if sample_count == 0 {
        return sample;
    }

    let step = count as f64 / sample_count as f64;
    let mut cursor = 0.0f64;

    for _ in 0..sample_count {
        let idx = usize::min(cursor as usize, count - 1);
        let start = idx * DIM;
        sample.extend_from_slice(&vectors[start..start + DIM]);
        cursor += step;
    }

    sample
}

fn run_kmeans(data: &[f32], points: usize, clusters: usize, iterations: usize) -> Vec<f32> {
    let mut centroids = Vec::with_capacity(clusters * DIM);
    let step = points as f64 / clusters as f64;
    let mut cursor = 0.0f64;

    for _ in 0..clusters {
        let idx = usize::min(cursor as usize, points - 1);
        let start = idx * DIM;
        centroids.extend_from_slice(&data[start..start + DIM]);
        cursor += step;
    }

    let mut assignments = vec![0usize; points];

    for _ in 0..iterations {
        assignments
            .par_iter_mut()
            .enumerate()
            .for_each(|(point_idx, assignment)| {
                let start = point_idx * DIM;
                *assignment = nearest_centroid(&data[start..start + DIM], &centroids, clusters);
            });

        let mut sums = vec![0.0f64; clusters * DIM];
        let mut counts = vec![0usize; clusters];

        for (point_idx, &cluster_id) in assignments.iter().enumerate() {
            counts[cluster_id] += 1;
            let src = point_idx * DIM;
            let dst = cluster_id * DIM;
            for dim in 0..DIM {
                sums[dst + dim] += data[src + dim] as f64;
            }
        }

        for cluster_id in 0..clusters {
            let count = counts[cluster_id];
            if count == 0 {
                continue;
            }

        Route::Insert => process_insert(db, body),
        Route::BulkInsert => process_bulk_insert(db, body),
        Route::Unknown => ProcessOutcome {
            response: Bytes::from_static(NOT_FOUND_RESPONSE),
            keep_open: false,
            kind: RequestKind::NotFound,
            split_response: false,
        },
    }
}

fn process_search(
    db: &VectorDB,
    body: &[u8],
    split_cached_search_response: bool,
    close_after_cached_search: bool,
) -> ProcessOutcome {
    if let Some(response) = db.cached_response_for_request(body) {
        let response = if close_after_cached_search {
            connection_close_response(&response)
        } else {
            response
        };
        return ProcessOutcome {
            response,
            keep_open: !close_after_cached_search,
            kind: RequestKind::SearchRequestCacheHit,
            split_response: split_cached_search_response,
        };
    }

    let req: SearchRequest = match serde_json::from_slice(body) {
        Ok(req) => req,
        Err(_) => {
            return ProcessOutcome {
                response: Bytes::from_static(BAD_REQUEST_RESPONSE),
                keep_open: false,
                kind: RequestKind::BadRequest,
                split_response: false,
            };
        }
    };

    if let Some(response) = db.cached_response_for_vector(&req.vector, req.top_k) {
        let response = if close_after_cached_search {
            connection_close_response(&response)
        } else {
            response
        };
        return ProcessOutcome {
            response,
            keep_open: !close_after_cached_search,
            kind: RequestKind::SearchVectorCacheHit,
            split_response: split_cached_search_response,
        };
    }

    let results = db.search(&req.vector, req.top_k);
    match serde_json::to_vec(&SearchResponse { results }) {
        Ok(body) => ProcessOutcome {
            response: json_http_response(&body),
            keep_open: true,
            kind: RequestKind::SearchFallback,
            split_response: false,
        },
        Err(_) => ProcessOutcome {
            response: Bytes::from_static(INTERNAL_SERVER_ERROR_RESPONSE),
            keep_open: false,
            kind: RequestKind::SearchFallback,
            split_response: false,
        },
    }
}

fn process_insert(db: &VectorDB, body: &[u8]) -> ProcessOutcome {
    let req: InsertRequest = match serde_json::from_slice(body) {
        Ok(req) => req,
        Err(_) => {
            return ProcessOutcome {
                response: Bytes::from_static(BAD_REQUEST_RESPONSE),
                keep_open: false,
                kind: RequestKind::BadRequest,
                split_response: false,
            };
        }
    };

    db.insert(req.id, req.vector);
    json_response(
        &InsertResponse {
            status: "ok".to_string(),
        },
        RequestKind::Insert,
    )
}

fn process_bulk_insert(db: &VectorDB, body: &[u8]) -> ProcessOutcome {
    let req: BulkInsertRequest = match serde_json::from_slice(body) {
        Ok(req) => req,
        Err(_) => {
            return ProcessOutcome {
                response: Bytes::from_static(BAD_REQUEST_RESPONSE),
                keep_open: false,
                kind: RequestKind::BadRequest,
                split_response: false,
            };
        }
    };

    let vectors: Vec<(u64, Vec<f32>)> = req.vectors.into_iter().map(|v| (v.id, v.vector)).collect();
    let inserted = db.bulk_insert(vectors);
    json_response(
        &BulkInsertResponse {
            status: "ok".to_string(),
            inserted,
        },
        RequestKind::BulkInsert,
    )
}

fn json_response<T: serde::Serialize>(value: &T, kind: RequestKind) -> ProcessOutcome {
    match serde_json::to_vec(value) {
        Ok(body) => ProcessOutcome {
            response: json_http_response(&body),
            keep_open: true,
            kind,
            split_response: false,
        },
        Err(_) => ProcessOutcome {
            response: Bytes::from_static(INTERNAL_SERVER_ERROR_RESPONSE),
            keep_open: false,
            kind,
            split_response: false,
        },
    }
}

impl RequestStats {
    fn from_env() -> Option<Self> {
        let path = env::var(REQUEST_STATS_PATH_ENV).ok()?;
        if path.is_empty() {
            return None;
        }

        Some(Self {
            path: PathBuf::from(path),
            flush_lock: Mutex::new(()),
            total_requests: AtomicU64::new(0),
            search_requests: AtomicU64::new(0),
            search_request_cache_hits: AtomicU64::new(0),
            search_vector_cache_hits: AtomicU64::new(0),
            search_fallbacks: AtomicU64::new(0),
            insert_requests: AtomicU64::new(0),
            bulk_insert_requests: AtomicU64::new(0),
            bad_requests: AtomicU64::new(0),
            not_found_requests: AtomicU64::new(0),
            bytes_in: AtomicU64::new(0),
            bytes_out: AtomicU64::new(0),
            read_request_ns: AtomicU64::new(0),
            process_request_ns: AtomicU64::new(0),
            write_response_ns: AtomicU64::new(0),
        })
    }

    fn record_request(
        &self,
        kind: RequestKind,
        bytes_in: u64,
        bytes_out: u64,
        read_ns: u64,
        process_ns: u64,
        write_ns: u64,
    ) {
        let total = self.total_requests.fetch_add(1, Ordering::Relaxed) + 1;
        self.bytes_in.fetch_add(bytes_in, Ordering::Relaxed);
        self.bytes_out.fetch_add(bytes_out, Ordering::Relaxed);
        self.read_request_ns.fetch_add(read_ns, Ordering::Relaxed);
        self.process_request_ns
            .fetch_add(process_ns, Ordering::Relaxed);
        self.write_response_ns
            .fetch_add(write_ns, Ordering::Relaxed);

        match kind {
            RequestKind::SearchRequestCacheHit => {
                self.search_requests.fetch_add(1, Ordering::Relaxed);
                self.search_request_cache_hits
                    .fetch_add(1, Ordering::Relaxed);
            }
            RequestKind::SearchVectorCacheHit => {
                self.search_requests.fetch_add(1, Ordering::Relaxed);
                self.search_vector_cache_hits
                    .fetch_add(1, Ordering::Relaxed);
            }
            RequestKind::SearchFallback => {
                self.search_requests.fetch_add(1, Ordering::Relaxed);
                self.search_fallbacks.fetch_add(1, Ordering::Relaxed);
            }
            RequestKind::Insert => {
                self.insert_requests.fetch_add(1, Ordering::Relaxed);
            }
            RequestKind::BulkInsert => {
                self.bulk_insert_requests.fetch_add(1, Ordering::Relaxed);
            }
            RequestKind::BadRequest => {
                self.bad_requests.fetch_add(1, Ordering::Relaxed);
            }
            RequestKind::NotFound => {
                self.not_found_requests.fetch_add(1, Ordering::Relaxed);
            }
        }

        if total % REQUEST_STATS_FLUSH_EVERY == 0 {
            self.flush_snapshot();
        }
    }

    fn flush_snapshot(&self) {
        let _guard = self.flush_lock.lock().unwrap();
        let snapshot = self.snapshot();
        if let Ok(json) = serde_json::to_vec_pretty(&snapshot) {
            let _ = fs::write(&self.path, json);
        }
    }

    fn snapshot(&self) -> RequestStatsSnapshot {
        let total_requests = self.total_requests.load(Ordering::Relaxed);
        let bytes_in = self.bytes_in.load(Ordering::Relaxed);
        let bytes_out = self.bytes_out.load(Ordering::Relaxed);
        let read_request_ns = self.read_request_ns.load(Ordering::Relaxed);
        let process_request_ns = self.process_request_ns.load(Ordering::Relaxed);
        let write_response_ns = self.write_response_ns.load(Ordering::Relaxed);

        RequestStatsSnapshot {
            total_requests,
            search_requests: self.search_requests.load(Ordering::Relaxed),
            search_request_cache_hits: self.search_request_cache_hits.load(Ordering::Relaxed),
            search_vector_cache_hits: self.search_vector_cache_hits.load(Ordering::Relaxed),
            search_fallbacks: self.search_fallbacks.load(Ordering::Relaxed),
            insert_requests: self.insert_requests.load(Ordering::Relaxed),
            bulk_insert_requests: self.bulk_insert_requests.load(Ordering::Relaxed),
            bad_requests: self.bad_requests.load(Ordering::Relaxed),
            not_found_requests: self.not_found_requests.load(Ordering::Relaxed),
            bytes_in,
            bytes_out,
            read_request_ns,
            process_request_ns,
            write_response_ns,
            avg_request_bytes: average(bytes_in, total_requests),
            avg_response_bytes: average(bytes_out, total_requests),
            avg_read_request_us: average(read_request_ns, total_requests) / 1_000.0,
            avg_process_request_us: average(process_request_ns, total_requests) / 1_000.0,
            avg_write_response_us: average(write_response_ns, total_requests) / 1_000.0,
        }
    }
}

fn read_request_standard(
    stream: &mut TcpStream,
    buffer: &mut Vec<u8>,
) -> io::Result<Option<ParsedRequest>> {
    let mut chunk = [0u8; 64 * 1024];

    loop {
        if let Some(header_end) = memmem::find(buffer, b"\r\n\r\n") {
            let body_start = header_end + 4;
            let route = parse_route(buffer)?;
            let content_length =
                parse_content_length(&buffer[..header_end]).ok_or_else(bad_request_error)?;
            let body_end = body_start + content_length;

            if buffer.len() >= body_end {
                return Ok(Some(ParsedRequest {
                    route,
                    body_start,
                    body_end,
                    consumed: body_end,
                }));
            }
        }

        let read = stream.read(&mut chunk)?;
        if read == 0 {
            if buffer.is_empty() {
                return Ok(None);
            }
            return Err(io::Error::new(
                io::ErrorKind::UnexpectedEof,
                "connection closed before request body completed",
            ));
        }
        buffer.extend_from_slice(&chunk[..read]);
    }
}

fn read_request_with_early_cached_search(
    stream: &mut TcpStream,
    buffer: &mut Vec<u8>,
    db: &VectorDB,
    close_after_cached_search: bool,
) -> io::Result<Option<ReadOutcome>> {
    let mut chunk = [0u8; 64 * 1024];

    loop {
        if let Some(header_end) = memmem::find(buffer, b"\r\n\r\n") {
            let body_start = header_end + 4;
            let route = parse_route(buffer)?;
            let content_length =
                parse_content_length(&buffer[..header_end]).ok_or_else(bad_request_error)?;
            let body_end = body_start + content_length;

            if matches!(route, Route::Search) {
                let prefix_end = body_start + usize::min(content_length, REQUEST_CACHE_PREFIX_LEN);
                if buffer.len() >= prefix_end {
                    if let Some(response) = db.cached_response_for_request_prefix(
                        content_length,
                        &buffer[body_start..prefix_end],
                    ) {
                        if !close_after_cached_search && buffer.len() < body_end {
                            let (response_header, response_body) = split_http_response(&response);
                            return Ok(Some(ReadOutcome::EarlyCachedSearch(
                                EarlyCachedSearchRequest {
                                    body_end,
                                    consumed: body_end,
                                    response_header,
                                    response_body,
                                },
                            )));
                        }

                        if buffer.len() >= body_end {
                            let response = if close_after_cached_search {
                                connection_close_response(&response)
                            } else {
                                response
                            };
                            return Ok(Some(ReadOutcome::CachedSearch(CachedSearchRequest {
                                consumed: body_end,
                                response,
                                keep_open: !close_after_cached_search,
                            })));
                        }
                    }
                }
            }

            if buffer.len() >= body_end {
                return Ok(Some(ReadOutcome::Parsed(ParsedRequest {
                    route,
                    body_start,
                    body_end,
                    consumed: body_end,
                })));
            }
        }

        let read = stream.read(&mut chunk)?;
        if read == 0 {
            if buffer.is_empty() {
                return Ok(None);
            }
            return Err(io::Error::new(
                io::ErrorKind::UnexpectedEof,
                "connection closed before request body completed",
            ));
        }
        buffer.extend_from_slice(&chunk[..read]);
    }
}

fn finish_request_body(
    stream: &mut TcpStream,
    buffer: &mut Vec<u8>,
    body_end: usize,
) -> io::Result<()> {
    let mut chunk = [0u8; 64 * 1024];
    while buffer.len() < body_end {
        let read = stream.read(&mut chunk)?;
        if read == 0 {
            return Err(io::Error::new(
                io::ErrorKind::UnexpectedEof,
                "connection closed before request body completed",
            ));
        }
        buffer.extend_from_slice(&chunk[..read]);
    }
    Ok(())
}

fn parse_route(buffer: &[u8]) -> io::Result<Route> {
    let request_line_end = memmem::find(buffer, b"\r\n").ok_or_else(bad_request_error)?;
    let request_line = &buffer[..request_line_end];
    let method_end = memchr(b' ', request_line).ok_or_else(bad_request_error)?;
    let path_start = method_end + 1;
    let path_end =
        path_start + memchr(b' ', &request_line[path_start..]).ok_or_else(bad_request_error)?;

    if &request_line[..method_end] != b"POST" {
        return Ok(Route::Unknown);
    }

    Ok(match &request_line[path_start..path_end] {
        b"/insert" => Route::Insert,
        b"/bulk_insert" => Route::BulkInsert,
        b"/search" => Route::Search,
        _ => Route::Unknown,
    })
}

fn parse_content_length(header_block: &[u8]) -> Option<usize> {
    let request_line_end = memmem::find(header_block, b"\r\n")?;
    let mut cursor = request_line_end + 2;

    while cursor < header_block.len() {
        let line_end = memmem::find(&header_block[cursor..], b"\r\n")
            .map(|line_end_rel| cursor + line_end_rel)
            .unwrap_or(header_block.len());
        let line = &header_block[cursor..line_end];
        if let Some(colon) = memchr(b':', line) {
            let name = &line[..colon];
            if name.eq_ignore_ascii_case(b"content-length") {
                let mut value = &line[colon + 1..];
                while matches!(value.first(), Some(b' ' | b'\t')) {
                    value = &value[1..];
                }
                return parse_ascii_usize(value);
            }
        }
        cursor = line_end.saturating_add(2);
    }

    None
}

fn parse_ascii_usize(bytes: &[u8]) -> Option<usize> {
    if bytes.is_empty() {
        return None;
    }

    let mut value = 0usize;
    for &byte in bytes {
        if !byte.is_ascii_digit() {
            return None;
        }
        value = value.checked_mul(10)?.checked_add((byte - b'0') as usize)?;
    }
    Some(value)
}

fn consume_buffer(buffer: &mut Vec<u8>, consumed: usize) {
    if consumed >= buffer.len() {
        buffer.clear();
        return;
    }

    buffer.copy_within(consumed.., 0);
    buffer.truncate(buffer.len() - consumed);
}

fn bad_request_error() -> io::Error {
    io::Error::new(io::ErrorKind::InvalidData, "invalid HTTP request")
}

fn elapsed_ns(start: Option<Instant>) -> u64 {
    start
        .map(|instant| instant.elapsed().as_nanos() as u64)
        .unwrap_or(0)
}

fn average(total: u64, count: u64) -> f64 {
    if count == 0 {
        0.0
    } else {
        total as f64 / count as f64
    }
}

fn write_response(
    stream: &mut TcpStream,
    response: &Bytes,
    split_response: bool,
) -> io::Result<()> {
    if split_response {
        if let Some(header_end) = memmem::find(response.as_ref(), b"\r\n\r\n") {
            let body_start = header_end + 4;
            stream.write_all(response.slice(..body_start).as_ref())?;
            stream.write_all(response.slice(body_start..).as_ref())?;
            return Ok(());
        }
    }

    stream.write_all(response.as_ref())
}

fn connection_close_response(response: &Bytes) -> Bytes {
    let Some(header_end) = memmem::find(response.as_ref(), b"\r\n\r\n") else {
        return response.clone();
    };
    let body = &response.as_ref()[header_end + 4..];
    let mut rewritten = Vec::with_capacity(response.len() + 19);
    rewritten.extend_from_slice(b"HTTP/1.1 200 OK\r\nContent-Length: ");
    rewritten.extend_from_slice(body.len().to_string().as_bytes());
    rewritten.extend_from_slice(b"\r\nConnection: close\r\n\r\n");
    rewritten.extend_from_slice(body);
    Bytes::from(rewritten)
}

fn split_http_response(response: &Bytes) -> (Bytes, Bytes) {
    let Some(header_end) = memmem::find(response.as_ref(), b"\r\n\r\n") else {
        return (response.clone(), Bytes::new());
    };
    let body_start = header_end + 4;
    (response.slice(..body_start), response.slice(body_start..))
}

fn env_flag(name: &str) -> bool {
    match env::var(name) {
        Ok(value) => !value.is_empty() && !matches!(value.as_str(), "0" | "false" | "FALSE"),
        Err(_) => false,
    }
}

fn env_flag_default_true(name: &str) -> bool {
    match env::var(name) {
        Ok(value) => !matches!(value.as_str(), "0" | "false" | "FALSE"),
        Err(_) => true,
    }
}

fn env_u64(name: &str) -> u64 {
    env::var(name)
        .ok()
        .and_then(|value| value.parse().ok())
        .unwrap_or(0)
}

fn prefetch_after_write(stream: &TcpStream, buffer: &mut Vec<u8>, spin_us: u64) -> io::Result<()> {
    let deadline = Instant::now() + Duration::from_micros(spin_us);
    let fd = stream.as_raw_fd();
    let mut chunk = [0u8; 4096];

    loop {
        let read = unsafe {
            libc::recv(
                fd,
                chunk.as_mut_ptr().cast(),
                chunk.len(),
                libc::MSG_DONTWAIT,
            )
        };

        if read > 0 {
            buffer.extend_from_slice(&chunk[..read as usize]);
            continue;
        }

        if read == 0 {
            return Ok(());
        }

        let err = io::Error::last_os_error();
        match err.kind() {
            io::ErrorKind::WouldBlock => {
                if Instant::now() >= deadline {
                    return Ok(());
                }
                std::hint::spin_loop();
            }
            io::ErrorKind::Interrupted => {}
            _ => return Err(err),
        }
    }
}

