class AgentLogger:
    def __init__(self, work_dir: Path):
        self.path = work_dir / "agent_log.jsonl"
        self.handle = self.path.open("a", encoding="utf-8")
        self.iteration = 0

    def close(self) -> None:
        self.handle.close()

    def _log(self, event: JsonDict) -> None:
        self.handle.write(json.dumps(event, ensure_ascii=False) + "\n")
        self.handle.flush()

    def log_session_start(self, model: str, work_dir: str, thinking_mode: str) -> None:
        self._log(
            {
                "event": "session_start",
                "model": model,
                "work_dir": work_dir,
                "thinking_mode": thinking_mode,
                "timestamp": _now_rfc3339(),
            }
        )

    def log_llm_request(self, message_count: int) -> None:
        self.iteration += 1
        self._log(
            {
                "event": "llm_request",
                "iteration": self.iteration,
                "message_count": message_count,
                "timestamp": _now_rfc3339(),
            }
        )

    def log_llm_response(
        self,
        *,
        has_tool_calls: bool,
        tool_call_count: int,
        content: str | None,
        thinking_content: str | None,
        duration_ms: int,
